// Test 1: the request must return status 200
pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// Test 2: the response must arrive in a reasonable time
pm.test("Response time is under 2000 ms", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

// Test 3: the body must contain the expected fields and the right post
pm.test("Response has the expected fields", function () {
    const body = pm.response.json();
    pm.expect(body).to.have.property("userId");
    pm.expect(body).to.have.property("id", 1);
    pm.expect(body).to.have.property("title");
    pm.expect(body).to.have.property("body");
});

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// The API returns 100 posts in total
pm.test("Response is an array of 100 posts", function () {
    const posts = pm.response.json();
    pm.expect(posts).to.be.an("array");
    pm.expect(posts).to.have.lengthOf(100);
});

// Checking the first post as a sample of the structure
pm.test("First post has exactly the expected fields", function () {
    const first = pm.response.json()[0];
    pm.expect(first).to.have.all.keys("userId", "id", "title", "body");
});

// POST that creates a resource should return 201 Created, not 200
pm.test("Status code is 201 Created", function () {
    pm.response.to.have.status(201);
});

// The API must return the same data we sent
pm.test("Response echoes the data we sent", function () {
    const body = pm.response.json();
    pm.expect(body.title).to.eql("QA test post");
    pm.expect(body.body).to.eql("Created from Postman");
    pm.expect(body.userId).to.eql(1);
});

pm.test("Response includes a new id", function () {
    pm.expect(pm.response.json()).to.have.property("id");
});

// A post that does not exist must return 404
pm.test("Status code is 404 Not Found", function () {
    pm.response.to.have.status(404);
});

pm.test("Body is empty for a post that does not exist", function () {
    pm.expect(pm.response.json()).to.be.empty;
});

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// The API must return the updated values, not the old ones
pm.test("Response contains the updated data", function () {
    const body = pm.response.json();
    pm.expect(body.title).to.eql("Updated title");
    pm.expect(body.body).to.eql("Updated from Postman");
});

// The id must stay the same: we updated post 1, not created a new one
pm.test("Post id is still 1", function () {
    pm.expect(pm.response.json().id).to.eql(1);
});

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

// This API returns an empty object after deleting
pm.test("Response body is empty", function () {
    pm.expect(pm.response.json()).to.be.empty;
});
